const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const SECTIONS=['inicio','conceptos','simulador','comprobacion','recursos','cierre'];
let conceptIndex=0, resourceContext=null, currentUtter=null, toneCtx=null;
const state={section:'inicio',font:1,sound:true,layout:'auto',theme:'light',concepts:{},quizOrder:[],quizIndex:0,quizStates:{},quizScore:0,lab:'personal',stress:{drop:false,late:false}};
function esc(v=''){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function n(v,d=0){const x=Number(v);return Number.isFinite(x)?x:d;}
function money(v){return new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',maximumFractionDigits:0}).format(Math.max(0,v||0));}
function pct(v){return `${Math.round(v)}%`;}
function randomInt(max){if(max<=1)return 0;try{if(window.crypto?.getRandomValues){const limit=Math.floor(0x100000000/max)*max,buf=new Uint32Array(1);let x;do{window.crypto.getRandomValues(buf);x=buf[0];}while(x>=limit);return x%max;}}catch(e){}return Math.floor(Math.random()*max);}
function shuffleIndices(n){const a=[...Array(n).keys()];for(let i=a.length-1;i>0;i--){const j=randomInt(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;}
let conceptCorrectPositions=null;
function buildConceptCorrectPositions(){const total=DATA?.concepts?.length||0;if(!total)return[];for(let attempt=0;attempt<500;attempt++){const pos=Array.from({length:total},(_,i)=>randomInt(Math.max(1,DATA.concepts[i].options.length)));const counts={};pos.forEach(x=>counts[x]=(counts[x]||0)+1);const maxCount=Math.max(...Object.values(counts)),unique=Object.keys(counts).length;if(maxCount<=Math.ceil(total/2)&&unique>=Math.min(3,total))return pos;}return Array.from({length:total},(_,i)=>i%Math.max(1,DATA.concepts[i].options.length)).sort(()=>randomInt(3)-1);}
function conceptOrder(c){if(!conceptCorrectPositions)conceptCorrectPositions=buildConceptCorrectPositions();const idx=DATA.concepts.findIndex(x=>x.id===c.id),correct=c.options.findIndex(x=>x[1]),target=conceptCorrectPositions[idx]??randomInt(c.options.length),others=shuffleIndices(c.options.length).filter(i=>i!==correct);others.splice(Math.min(target,others.length),0,correct);return others;}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._tm);t._tm=setTimeout(()=>t.classList.remove('show'),1900);}
function beep(kind='ok'){if(!state.sound)return;try{toneCtx=toneCtx||new (window.AudioContext||window.webkitAudioContext)();const o=toneCtx.createOscillator(),g=toneCtx.createGain();o.frequency.value=kind==='bad'?220:kind==='soft'?420:640;g.gain.setValueAtTime(.0001,toneCtx.currentTime);g.gain.exponentialRampToValueAtTime(.05,toneCtx.currentTime+.01);g.gain.exponentialRampToValueAtTime(.0001,toneCtx.currentTime+.10);o.connect(g);g.connect(toneCtx.destination);o.start();o.stop(toneCtx.currentTime+.11);}catch(e){}}
function go(section){if(!SECTIONS.includes(section))return;closeAllDialogs();state.section=section;$$('.section').forEach(s=>s.classList.toggle('active',s.id===section));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.go===section));window.scrollTo({top:0,behavior:'smooth'});if(section==='conceptos')renderConceptCards();if(section==='simulador')renderLab();if(section==='comprobacion')ensureQuiz();if(section==='recursos')renderResources();}
function openDialog(id){const d=$('#'+id);if(!d)return;try{if(!d.open)d.showModal();document.body.classList.add('dialog-open');}catch(e){d.setAttribute('open','');document.body.classList.add('dialog-open');}}
function closeDialog(id){const d=$('#'+id);if(!d)return;stopSpeech();$$('audio,video',d).forEach(m=>{try{m.pause();}catch(e){}});try{if(d.open)d.close();}catch(e){d.removeAttribute('open');}if(!$$('dialog[open]').length)document.body.classList.remove('dialog-open');}
function closeAllDialogs(){$$('dialog[open]').forEach(d=>closeDialog(d.id));}
function toggleFullscreen(el){if(!document.fullscreenElement){el.requestFullscreen?.().catch(()=>{});}else document.exitFullscreen?.().catch(()=>{});}
function applyLayout(){let active=state.layout;if(active==='auto')active=innerWidth/Math.max(innerHeight,1)>1.5?'16x9':'4x3';document.documentElement.dataset.layoutActive=active;document.documentElement.dataset.layoutMode=state.layout;$('#layoutSelect').value=state.layout;}
function updateFont(){document.documentElement.style.setProperty('--font-scale',state.font.toFixed(2));}
function applyTheme(){document.documentElement.dataset.theme=state.theme;const b=$('#themeBtn');b.textContent=state.theme==='dark'?'☀':'◐';b.setAttribute('aria-pressed',state.theme==='dark'?'true':'false');}

/* speech */
function pickVoice(){const vs=speechSynthesis.getVoices?.()||[];for(const lang of ['es-PE','es-419','es-MX','es-US','es']){const v=vs.find(x=>(x.lang||'').toLowerCase()===lang.toLowerCase())||vs.find(x=>(x.lang||'').toLowerCase().startsWith(lang.toLowerCase()));if(v)return v;}return vs.find(x=>(x.lang||'').toLowerCase().startsWith('es'))||null;}
function speak(text){if(!text||!('speechSynthesis'in window))return;stopSpeech();currentUtter=new SpeechSynthesisUtterance(text);currentUtter.lang='es-PE';const v=pickVoice();if(v)currentUtter.voice=v;currentUtter.rate=.96;speechSynthesis.speak(currentUtter);}
function stopSpeech(){if('speechSynthesis'in window)speechSynthesis.cancel();currentUtter=null;}function pauseSpeech(){speechSynthesis?.pause?.();}function resumeSpeech(){speechSynthesis?.resume?.();}
function speechControlsHTML(){return `<div class="speech-controls"><button type="button" data-speech="read">▶ Leer</button><button type="button" data-speech="explain">💡 Explicar</button><button type="button" data-speech="pause">Ⅱ Pausar</button><button type="button" data-speech="resume">↻ Continuar</button><button type="button" data-speech="stop">■ Detener</button></div>`;}
function bindSpeechControls(root,getText){$$('[data-speech]',root).forEach(b=>b.onclick=()=>{const a=b.dataset.speech;if(a==='pause')return pauseSpeech();if(a==='resume')return resumeSpeech();if(a==='stop')return stopSpeech();const t=getText(a);if(t)speak(t);});}
function slideText(slide,type){return RT.ppt?.[Math.max(0,slide-1)]?.[type]||'';}

/* question engine */
function createQState(q){return{order:shuffleIndices(q.options.length),selected:null,firstWrong:null,phase:'select1',result:null};}
function questionDone(s){return s.phase==='correct'||s.phase==='route';}
function feedbackGrid(items){return `<div class="feedback-grid">${items.map(x=>`<div><strong>${esc(x[0])}</strong><p>${esc(x[1])}</p></div>`).join('')}</div>`;}
function renderQuestion(host,q,s,cfg={}){
 if(!s.order)s.order=shuffleIndices(q.options.length);const locked=s.phase==='firstWrong'||questionDone(s);
 const opts=s.order.map((orig,pos)=>{const [text,ok]=q.options[orig],selected=s.selected===orig,firstWrong=s.firstWrong===orig,route=s.phase==='route';return `<button type="button" class="${['option',selected?'selected':'',firstWrong?'wrong-choice':'',route&&ok?'correct-choice':''].filter(Boolean).join(' ')}" data-opt="${orig}" ${(locked||(s.phase==='select2'&&firstWrong))?'disabled':''}><strong>${String.fromCharCode(65+pos)}.</strong> ${esc(text)}</button>`;}).join('');
 let feedback='';
 if(s.phase==='correct')feedback=`<div class="feedback good" data-feedback><div class="feedback-title"><span>✓</span><div><h4>Respuesta correcta</h4><p>Revisa el razonamiento, no solo el resultado.</p></div></div><p class="feedback-main">${esc(q.correct)}</p>${feedbackGrid([['Por qué es correcta',q.correct],['Cómo se aplica',q.application],['Por qué no las otras',q.contrast],['Regla transferible',q.rule]])}<div class="feedback-closing"><strong>Idea clave:</strong> en crédito, una respuesta defendible conecta dato, evidencia, riesgo y decisión.</div></div>`;
 else if(s.phase==='firstWrong'){const chosen=q.options[s.firstWrong]?.[0]||'';feedback=`<div class="feedback bad" data-feedback><div class="feedback-title"><span>↺</span><div><h4>Primer intento incorrecto</h4><p>Todavía no mostramos la respuesta correcta.</p></div></div><p class="feedback-main">${esc(q.wrong1)}</p>${feedbackGrid([['Tu elección',chosen],['Qué revisar','Separa segmento, capacidad, actitud, evidencia y política antes de volver a elegir.'],['Pista',q.rule],['Segundo intento','Pulsa “Cambiar respuesta · segundo intento”. La alternativa anterior quedará bloqueada.']])}</div>`;}
 else if(s.phase==='route'){const correct=q.options.find(x=>x[1])?.[0]||'';feedback=`<div class="feedback route" data-feedback><div class="feedback-title"><span>→</span><div><h4>Ruta correcta</h4><p>El segundo intento también fue incorrecto. Reconstruimos el criterio paso a paso.</p></div></div><p class="feedback-main">${esc(q.routeSummary)}</p><ol class="route-steps">${(q.route||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${feedbackGrid([['Alternativa defendible',correct],['Por qué corresponde',q.correct],['Aplicación',q.application],['Por qué se descartan las otras',q.contrast],['Regla que debes conservar',q.rule]])}<div class="feedback-closing"><strong>Observa:</strong> la alternativa correcta quedó seleccionada y resaltada en verde.</div></div>`;}
 const label=s.phase==='select1'?'Intento 1 de 2':s.phase==='firstWrong'?'Primer intento revisado':s.phase==='select2'?'Intento 2 de 2':s.phase==='correct'?'Pregunta completada':'Ruta correcta';
 const actions=s.phase==='select1'||s.phase==='select2'?`<button class="btn primary" data-check ${s.selected===null?'disabled':''}>Comprobar respuesta</button>`:s.phase==='firstWrong'?`<button class="btn orange" data-change>Cambiar respuesta · segundo intento</button>`:'';
 host.innerHTML=`<div class="qbox"><div class="qmeta"><span class="attempt-badge">${label}</span></div><div class="question-prompt"><span class="question-label">PREGUNTA</span><p>${esc(q.text||q.question||'')}</p></div><div class="options">${opts}</div><div class="qactions">${actions}</div>${feedback}</div>`;
 $$('[data-opt]',host).forEach(b=>b.onclick=()=>{if(locked)return;s.selected=Number(b.dataset.opt);beep('soft');renderQuestion(host,q,s,cfg);});
 $('[data-check]',host)?.addEventListener('click',()=>{if(s.selected===null)return;const ok=!!q.options[s.selected][1];if(ok){s.phase='correct';beep('ok');renderQuestion(host,q,s,cfg);setTimeout(()=>$('[data-feedback]',host)?.scrollIntoView({behavior:'smooth',block:'nearest'}),30);cfg.onFinish?.({correct:true});}else if(s.phase==='select1'){s.firstWrong=s.selected;s.phase='firstWrong';beep('bad');renderQuestion(host,q,s,cfg);setTimeout(()=>$('[data-feedback]',host)?.scrollIntoView({behavior:'smooth',block:'nearest'}),30);}else{const correctIdx=q.options.findIndex(x=>x[1]);s.selected=correctIdx;s.phase='route';beep('bad');renderQuestion(host,q,s,cfg);setTimeout(()=>$('[data-feedback]',host)?.scrollIntoView({behavior:'smooth',block:'nearest'}),30);cfg.onFinish?.({correct:false});}});
 $('[data-change]',host)?.addEventListener('click',()=>{s.selected=null;s.phase='select2';beep('soft');renderQuestion(host,q,s,cfg);});
}

/* concepts */
function conceptState(c){if(!state.concepts[c.id]){const q=createQState(c);q.order=conceptOrder(c);state.concepts[c.id]={openQ:false,q};}return state.concepts[c.id];}
function renderConceptCards(){const host=$('#conceptGrid');host.innerHTML=DATA.concepts.map((c,i)=>{const s=conceptState(c),done=questionDone(s.q);return `<article class="concept-card" tabindex="0" data-concept="${i}"><div class="concept-card-inner"><div class="concept-face concept-front">${done?'<span class="concept-status">✓ Revisada</span>':''}<div class="concept-slide-thumb"><img src="assets/ppt/slide-${String(c.slide).padStart(2,'0')}.png" alt="${esc(c.title)}"></div><div class="concept-front-copy"><span class="concept-number">${c.number}</span><h3>${esc(c.title)}</h3><p>${esc(c.short)}</p><small>Pasa el mouse para ver el resumen · clic para abrir</small></div></div><div class="concept-face concept-back"><span class="concept-number">${c.number}</span><h3>${esc(c.title)}</h3><p>${esc(c.meaning)}</p><div class="open-cue">Haz clic para abrir →</div></div></div></article>`;}).join('');$$('[data-concept]',host).forEach(card=>{const fn=()=>openConcept(Number(card.dataset.concept));card.onclick=fn;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn();}};});const done=DATA.concepts.filter(c=>questionDone(conceptState(c).q)).length;$('#conceptProgress').textContent=`${done} / ${DATA.concepts.length} revisadas`;}
function openConcept(i){conceptIndex=Math.max(0,Math.min(DATA.concepts.length-1,i));renderConceptModal();openDialog('conceptModal');setTimeout(()=>$('#conceptBody').scrollTo({top:0}),20);}
function renderConceptModal(){const c=DATA.concepts[conceptIndex],s=conceptState(c),slide=`assets/ppt/slide-${String(c.slide).padStart(2,'0')}.png`;$('#conceptKicker').textContent=`Tarjeta ${c.number} · concepto aplicado`;$('#conceptTitle').textContent=c.title;$('#conceptCounter').textContent=`${conceptIndex+1} / ${DATA.concepts.length}`;$('#prevConcept').disabled=conceptIndex===0;$('#nextConcept').disabled=conceptIndex===DATA.concepts.length-1;const qp=s.openQ?'<div id="conceptQuestion"></div>':`<div class="question-gate"><div><strong>¿Listo para comprobar?</strong><span>Revisa primero el concepto, los apoyos y la pista de audio.</span></div><button class="btn primary" data-show-question>Ver pregunta →</button></div>`;let extra='';if(c.id==='segmentos')extra=`<div class="actions"><button class="btn orange" data-open-resource="video-short">▶ Ver microvideo completo · segmentación</button><button class="btn secondary" data-open-resource="ppt" data-resource-index="2">Ver comparación de segmentos</button></div>`;if(c.id==='motor')extra=`<div class="actions"><button class="btn orange" data-open-resource="video-clip">▶ Ver extracto · evaluación dual</button><button class="btn secondary" data-open-resource="ppt" data-resource-index="5">Ver motor PyME</button></div>`;if(c.id==='capacidad')extra=`<div class="actions"><button class="btn secondary" data-open-resource="ppt" data-resource-index="7">Ver fórmulas y avales</button><button class="btn secondary" data-open-resource="ppt" data-resource-index="9">Ver preevaluación exprés</button></div>`;if(c.id==='soluciones')extra=`<div class="actions"><button class="btn secondary" data-open-resource="ppt" data-resource-index="12">Ver activo fijo</button><button class="btn secondary" data-open-resource="ppt" data-resource-index="13">Ver leasing</button></div>`;
 $('#conceptBody').innerHTML=`<div class="concept-modal-layout"><div class="concept-image-column"><img class="concept-main-slide" src="${slide}" alt="Diapositiva de ${esc(c.title)}" data-image="${slide}">${speechControlsHTML()}</div><div class="concept-detail-scroll"><section class="detail-box"><span class="mini-label">QUÉ SIGNIFICA</span><p>${esc(c.meaning)}</p></section><section class="detail-box example"><span class="mini-label">EJEMPLO</span><p>${esc(c.example)}</p></section><section class="detail-box warning"><span class="mini-label">ERROR QUE CONVIENE EVITAR</span><p>${esc(c.error)}</p></section><div class="audio-pista"><strong>🎧 Extracto del audio antes de responder</strong><p>Úsalo como complemento breve. El audio completo queda disponible en Recursos.</p><audio controls preload="metadata"><source src="${c.audio}" type="audio/mp4"></audio></div>${extra}${qp}</div></div>`;
 bindSpeechControls($('#conceptBody'),type=>slideText(c.slide,type));$('[data-image]',$('#conceptBody'))?.addEventListener('click',e=>openImage(e.currentTarget.dataset.image,e.currentTarget.alt));$$('[data-open-resource]',$('#conceptBody')).forEach(b=>b.onclick=()=>openResource(b.dataset.openResource,Number(b.dataset.resourceIndex||0)));$('[data-show-question]',$('#conceptBody'))?.addEventListener('click',()=>{s.openQ=true;renderConceptModal();setTimeout(()=>$('#conceptQuestion')?.scrollIntoView({behavior:'smooth',block:'start'}),30);});if(s.openQ)renderQuestion($('#conceptQuestion'),c,s.q,{onFinish:renderConceptCards});}

/* laboratory */
const POLICIES={
 expansive:{name:'Expansivo',color:'green',threshold:65,rci:.30,rateAdj:-1,weights:{capacity:25,history:20,stability:15,debt:15,verify:10,profile:15}},
 balanced:{name:'Equilibrado',color:'amber',threshold:70,rci:.25,rateAdj:0,weights:{capacity:30,history:25,stability:15,debt:15,verify:10,profile:5}},
 conservative:{name:'Conservador',color:'blue',threshold:78,rci:.22,rateAdj:2,weights:{capacity:35,history:30,stability:15,debt:10,verify:10,profile:0}}
};
function field(label,name,value,help,type='number',attrs=''){return `<label class="lab-field"><span>${label}</span><input type="${type}" name="${name}" value="${value}" ${attrs}><small>${help}</small></label>`;}
function selectField(label,name,opts,help){return `<label class="lab-field"><span>${label}</span><select name="${name}">${opts.map(o=>`<option value="${o[0]}" ${o[2]?'selected':''}>${o[1]}</option>`).join('')}</select><small>${help}</small></label>`;}
function checkField(label,name,checked,help){return `<label class="lab-check"><input type="checkbox" name="${name}" ${checked?'checked':''}><span><strong>${label}</strong><small>${help}</small></span></label>`;}
const EVIDENCE_CONFIG={
 personal:{names:['evIncome','evTenure','evDebt','evHistory'],labels:['Ingreso sustentado','Antigüedad sustentada','Obligaciones verificadas','Historial revisado']},
 pyme:{names:['evSales','evTenure','evPatrimony','evHistory','evPurpose'],labels:['Ventas sustentadas','Antigüedad sustentada','Patrimonio sustentado','Historial revisado','Destino documentado']},
 empresa:{names:['evFs','evTax','evDebt','evPurpose'],labels:['Estados financieros disponibles','Información tributaria disponible','Reporte de obligaciones','Destino documentado']}
};
function evidenceGate(type,ev){const cfg=EVIDENCE_CONFIG[type],missing=cfg.labels.filter((_,i)=>!ev[i]);return{complete:missing.length===0,missing,count:ev.filter(Boolean).length,total:ev.length};}
function evidenceWarning(g){if(g.complete)return'';return `<div class="policy-alert evidence-warning"><strong>⚠ Evidencia pendiente de validar</strong><p>Falta verificar: ${g.missing.map(esc).join(', ')}. La evaluación puede continuar de forma preliminar, pero <b>no corresponde cerrar una aprobación definitiva ni avanzar al desembolso</b> hasta validar esta información.</p></div>`;}
function bindEvidenceWatcher(formSelector,type){const form=$(formSelector),cfg=EVIDENCE_CONFIG[type],note=form?.querySelector('[data-evidence-note]');if(!form||!note)return;const refresh=()=>{const missing=cfg.names.filter(n=>!form.elements[n]?.checked).map((n,i)=>cfg.labels[cfg.names.indexOf(n)]);if(!missing.length){note.className='evidence-note complete';note.innerHTML='✓ Evidencias mínimas disponibles para continuar con la evaluación.';}else{note.className='evidence-note warning';note.innerHTML=`⚠ Falta validar: <strong>${missing.map(esc).join(', ')}</strong>. Puedes continuar con el análisis preliminar, pero no cerrar aprobación ni desembolso.`;}};cfg.names.forEach(n=>form.elements[n]?.addEventListener('change',refresh));refresh();}
function commonLabHeader(title,sub,slide,audio){return `<div class="lab-support"><div class="lab-support-copy"><span class="eyebrow dark">HERRAMIENTA DIDÁCTICA</span><h3>${title}</h3><p>${sub}</p><div class="actions"><button class="btn secondary" data-open-resource="ppt" data-resource-index="${slide-1}">Ver apoyo PPT</button></div>${audio?`<div class="audio-pista compact"><strong>🎧 Pista breve del audio</strong><audio controls preload="metadata"><source src="${audio}" type="audio/mp4"></audio></div>`:''}</div><img src="assets/ppt/slide-${String(slide).padStart(2,'0')}.png" alt="Apoyo visual" data-image="assets/ppt/slide-${String(slide).padStart(2,'0')}.png"></div>`;}
function renderLab(){ $$('.lab-tab').forEach(b=>b.classList.toggle('active',b.dataset.lab===state.lab)); if(state.lab==='personal')renderPersonal(); else if(state.lab==='pyme')renderPyme(); else renderEmpresa(); }
function bindLabCommon(root){$$('[data-open-resource]',root).forEach(b=>b.onclick=()=>openResource(b.dataset.openResource,Number(b.dataset.resourceIndex||0)));$$('[data-image]',root).forEach(i=>i.onclick=e=>openImage(e.currentTarget.dataset.image,e.currentTarget.alt));}
function scoreBand(v){return v>=85?'Muy bueno':v>=75?'Bueno':v>=65?'Intermedio':'Alto riesgo';}
function annuityPV(payment,annualRate,months){const r=annualRate/100/12;if(r<=0)return payment*months;return payment*(1-Math.pow(1+r,-months))/r;}
function histRaw(v){return v==='good'?95:v==='minor'?68:25;}function consistencyPenalty(ref,cons,purpose){let s=100;if(ref==='mixed')s-=18;if(ref==='negative')s-=55;if(cons==='minor')s-=18;if(cons==='bad')s-=55;if(purpose==='unclear')s-=15;return Math.max(0,s);}
function qualitativeDecision(ref,cons,purpose){if(ref==='negative'||cons==='bad')return{level:'red',text:'Alerta cualitativa alta',effect:'La precalificación numérica no debería convertirse en desembolso mientras existan referencias negativas graves o información inconsistente.'};if(ref==='mixed'||cons==='minor'||purpose==='unclear')return{level:'amber',text:'Requiere validación',effect:'El expediente necesita aclaraciones o evidencia adicional antes de cerrar la decisión.'};return{level:'green',text:'Validación favorable',effect:'La información cualitativa es consistente con el perfil cuantitativo, sin que ello convierta la precalificación en desembolso automático.'};}
function renderPersonal(){const host=$('#labHost');host.innerHTML=`${commonLabHeader('Scoring Personal explicable','Modelo académico de 100 puntos. Cada dato muestra su origen y evidencia. Después comparamos tres políticas sin volver a ingresar la información.',8,'assets/pista_riesgo.m4a')}<form id="personalForm" class="lab-form"><div class="lab-grid">${selectField('Fuente principal de ingresos','incomeType',[['dependent','Dependiente · boleta de pago',true],['independent','Independiente · recibos por honorarios']], 'La fuente define qué evidencia de estabilidad conviene solicitar.')}${field('Edad','age',38,'Referencia del material: 21 a 69 años para persona natural.','number','min="18" max="80"')}${field('Ingreso bruto mensual (S/)','gross',8000,'Evidencia: boletas de pago o recibos por honorarios/abonos verificables.')}${field('Descuentos de ley (S/)','deductions',800,'Dato necesario para construir ingreso neto disponible.')}${field('Alquiler o cuota de vivienda (S/)','housing',1200,'Evidencia: contrato, voucher o cronograma de la obligación.')}${field('Antigüedad laboral / actividad (meses)','tenure',36,'Dependiente: contrato o constancia. Independiente: continuidad de actividad y comprobantes.')}${field('Recibos por honorarios disponibles','receipts',8,'Supuesto académico: si es independiente, usamos 6 recibos como mínimo didáctico para observar frecuencia.')}${field('Cuotas vigentes mensuales (S/)','current',500,'Evidencia: reporte de obligaciones y cronogramas vigentes.')}${field('Número de entidades con deuda','entities',2,'El número no decide solo, pero ayuda a observar concurrencia y dispersión de obligaciones.')}${field('Monto solicitado (S/)','requested',30000,'Monto a comparar con la capacidad estimada.')}${field('Plazo solicitado (meses)','term',36,'El plazo afecta la cuota estimada y el monto sostenible.')}${selectField('Historial crediticio','history',[['good','Ordenado / normal',true],['minor','Atrasos menores recientes'],['bad','Atrasos graves / deterioro']], 'Evidencia: información interna y externa disponible.')}</div><div class="evidence-box"><h4>Evidencias del dato</h4><div class="check-grid">${checkField('Ingreso sustentado','evIncome',true,'Boletas o recibos/abonos consistentes.')}${checkField('Antigüedad sustentada','evTenure',true,'Contrato, constancia o continuidad de actividad.')}${checkField('Obligaciones verificadas','evDebt',true,'Reporte de deuda y cuotas vigentes.')}${checkField('Historial revisado','evHistory',true,'Información crediticia disponible.')}</div><div class="evidence-note" data-evidence-note></div></div><div class="qual-box"><h4>Validación cualitativa · carácter y consistencia</h4><div class="lab-grid">${selectField('Referencias personales / comerciales','references',[['good','Favorables',true],['mixed','Mixtas / requieren aclaración'],['negative','Negativas relevantes']], 'No reemplazan el análisis numérico; aportan contexto sobre comportamiento y reputación.')}${selectField('Coherencia de la información','consistency',[['good','Consistente',true],['minor','Pequeñas diferencias por aclarar'],['bad','Contradicciones relevantes']], 'Se compara lo declarado con documentos y otras fuentes disponibles.')}${selectField('Destino del crédito','purpose',[['clear','Claro y sustentado',true],['unclear','Poco claro / sin sustento']], 'Un destino claro ayuda a evaluar coherencia y condiciones.')}</div></div><div class="actions"><button class="btn primary" type="submit">Evaluar y comparar escenarios</button></div></form><div id="personalResult"></div>`;bindLabCommon(host);bindEvidenceWatcher('#personalForm','personal');$('#personalForm').onsubmit=e=>{e.preventDefault();state.stress={drop:false,late:false};evaluatePersonal();};}
function personalData(){const f=new FormData($('#personalForm'));let gross=n(f.get('gross'));if(state.stress.drop)gross*=.8;let history=String(f.get('history'));if(state.stress.late&&history==='good')history='minor';return{incomeType:f.get('incomeType'),age:n(f.get('age')),gross,deductions:n(f.get('deductions')),housing:n(f.get('housing')),tenure:n(f.get('tenure')),receipts:n(f.get('receipts')),current:n(f.get('current')),entities:n(f.get('entities')),requested:n(f.get('requested')),term:Math.max(6,n(f.get('term'),36)),history,ev:[f.has('evIncome'),f.has('evTenure'),f.has('evDebt'),f.has('evHistory')],references:f.get('references'),consistency:f.get('consistency'),purpose:f.get('purpose')};}
function personalScenario(d,key){const p=POLICIES[key],net=Math.max(0,d.gross-d.deductions-d.housing),capacitySpace=Math.max(0,net*p.rci-d.current),capRaw=net?Math.max(0,Math.min(100,capacitySpace/(net*p.rci||1)*100)):0;let stability=d.tenure>=36?100:d.tenure>=24?90:d.tenure>=12?75:d.tenure>=6?55:30;if(d.incomeType==='independent'&&d.receipts<6)stability=Math.min(stability,50);const debtRaw=d.entities<=1?100:d.entities===2?85:d.entities===3?65:d.entities===4?45:25;const verifyRaw=d.ev.filter(Boolean).length/4*100;const profileRaw=d.age>=21&&d.age<=69?100:55;const raw={capacity:capRaw,history:histRaw(d.history),stability,debt:debtRaw,verify:verifyRaw,profile:profileRaw};let score=0;Object.entries(p.weights).forEach(([k,w])=>score+=raw[k]*w/100);score=Math.round(score);let rate=(score>=85?16:score>=75?21:score>=65?28:36)+p.rateAdj;const maxAmount=annuityPV(capacitySpace,rate,d.term),qual=qualitativeDecision(d.references,d.consistency,d.purpose);let initial=score>=p.threshold?(d.requested<=maxAmount?'Precalificación favorable':'Aprobable con ajuste de monto/plazo'):'Requiere revisión';if(capacitySpace<=0)initial='No precalifica por capacidad';let final=initial;const evidenceComplete=d.ev.every(Boolean);if(qual.level==='red')final='Observado · no avanzar a desembolso';else if(!evidenceComplete&&!initial.startsWith('No precalifica')&&!initial.startsWith('Requiere revisión'))final='Precalificación preliminar · evidencia pendiente';else if(qual.level==='amber'&&initial.startsWith('Precalificación'))final='Precalificación condicionada a validación';return{key,p,net,capacitySpace,raw,score,rate,maxAmount,initial,final,qual,evidenceComplete};}
function resultCards(results,type){return `<div class="compare-head"><div><span class="eyebrow dark">COMPARAR ESCENARIOS</span><h3>Mismos datos · distinto apetito de riesgo</h3><p>Las ponderaciones y umbrales cambian por política académica. El cliente no cambió.</p></div></div><div class="scenario-compare">${results.map(r=>`<article class="policy-card ${r.p.color}"><span class="policy-tag">${r.p.name}</span><div class="score-big">${type==='empresa'?Math.round(r.score):r.score}<small>${type==='empresa'?'/100':'/100'}</small></div><strong>${esc(r.final)}</strong>${r.maxAmount!==undefined?`<p>Monto estimado por capacidad: <b>${money(r.maxAmount)}</b></p><p>Tasa anual didáctica: <b>${r.rate.toFixed(1)}%</b></p>`:''}<p class="qual-${r.qual?.level||'green'}">${esc(r.qual?.text||r.note||'')}</p><details><summary>¿Cómo se calculó?</summary>${type==='personal'?personalBreakdown(r):type==='pyme'?pymeBreakdown(r):empresaBreakdown(r)}</details></article>`).join('')}</div>`;}
function personalBreakdown(r){const labels={capacity:'Capacidad',history:'Historial',stability:'Estabilidad',debt:'Concurrencia/deuda',verify:'Verificabilidad',profile:'Perfil complementario'};return `<div class="calc-list">${Object.keys(r.p.weights).map(k=>`<div><span>${labels[k]}</span><b>${Math.round(r.raw[k])}/100 × ${r.p.weights[k]}%</b></div>`).join('')}<div><span>Umbral de precalificación</span><b>${r.p.threshold}/100</b></div><div><span>RCI académico del escenario</span><b>${pct(r.p.rci*100)}</b></div></div>`;}
function stressControls(){return `<div class="stress-box"><div><strong>¿Qué pasaría si...?</strong><p>Aplica solo dos cambios para no alargar el recorrido.</p></div><label><input id="stressDrop" type="checkbox" ${state.stress.drop?'checked':''}> Ingresos / ventas caen 20 %</label><label><input id="stressLate" type="checkbox" ${state.stress.late?'checked':''}> Aparece un atraso reciente</label><button class="btn ghost" id="stressApply">Recalcular</button></div>`;}
function evaluatePersonal(){const d=personalData(),results=['expansive','balanced','conservative'].map(k=>personalScenario(d,k)),evg=evidenceGate('personal',d.ev);const host=$('#personalResult');host.innerHTML=`${evidenceWarning(evg)}<div class="lab-summary"><div><strong>Ingreso neto estimado</strong><span>${money(Math.max(0,d.gross-d.deductions-d.housing))}</span></div><div><strong>Evidencias completas</strong><span>${d.ev.filter(Boolean).length}/4</span></div><div><strong>Validación cualitativa</strong><span>${qualitativeDecision(d.references,d.consistency,d.purpose).text}</span></div></div>${resultCards(results,'personal')}${stressControls()}<div class="executive-report"><span class="eyebrow dark">LECTURA EJECUTIVA</span><p><strong>Qué se valoró:</strong> capacidad disponible, historial, estabilidad de la fuente de ingresos, concurrencia de deudas y calidad de la evidencia. La validación cualitativa se mantiene separada para recordar que un score alto no obliga a desembolsar.</p><p><strong>Lectura del caso:</strong> ${esc(results[1].final)} bajo política equilibrada. ${esc(results[1].qual.effect)}</p>${!evg.complete?`<p><strong>Estado documental:</strong> incompleto. Pendiente: ${esc(evg.missing.join(', '))}. La evaluación es preliminar y no habilita aprobación definitiva ni desembolso.</p>`:''}<div class="actions"><button class="btn secondary" id="readPersonalReport">▶ Leer</button><button class="btn secondary" id="explainPersonalReport">💡 Explicar</button></div></div>`;$('#stressApply').onclick=()=>{state.stress.drop=$('#stressDrop').checked;state.stress.late=$('#stressLate').checked;evaluatePersonal();};$('#readPersonalReport').onclick=()=>speak(`Resultado del scoring personal. Bajo política expansiva: ${results[0].final}. Equilibrada: ${results[1].final}. Conservadora: ${results[2].final}. La validación cualitativa es ${results[1].qual.text}.`);$('#explainPersonalReport').onclick=()=>speak('El comparador mantiene al mismo cliente y modifica únicamente ponderaciones, umbral y relación cuota ingreso académica. Por eso la decisión puede cambiar sin que cambie la persona. Luego se incorpora carácter y consistencia para evitar confundir precalificación con desembolso.');host.scrollIntoView({behavior:'smooth',block:'start'});}

function renderPyme(){const host=$('#labHost');host.innerHTML=`${commonLabHeader('Preevaluador PyME multidimensional','Evalúa negocio y titular. Los parámetros de la PPT se usan como referencia del ejercicio; no son reglas universales para todas las entidades.',10,'assets/pista_capacidad.m4a')}<form id="pymeForm" class="lab-form"><div class="lab-grid">${field('Ventas mensuales (S/)','sales',28000,'Evidencia: comprobantes, registros, declaraciones u otra trazabilidad comercial.')}${field('Antigüedad del negocio (meses)','tenure',36,'Evidencia: RUC, licencia, contratos u otros documentos de inicio/continuidad.')}${field('Edad del titular','age',42,'Referencia de la PPT: 21 a 69 años para persona natural.')}${field('Excedente mensual estimado (S/)','surplus',4500,'Debe surgir de ingresos menos costos, gastos y obligaciones del negocio.')}${field('Patrimonio neto estimado (S/)','patrimony',60000,'Evidencia: activos menos pasivos; patrimonio negativo es una alerta del material.')}${field('Número de entidades con deuda','entities',2,'Ayuda a observar concurrencia y dispersión de obligaciones.')}${selectField('Historial / actitud de pago','history',[['good','Ordenado / normal',true],['minor','Atrasos menores'],['bad','Deteriorado']], 'Se revisa con antecedentes internos y externos.')}${selectField('Actividad económica','activity',[['bakery','Panadería / alimentos',true],['commerce','Comercio'],['transport','Transporte público con un vehículo'],['lawyer','Abogado'],['accountant','Contador'],['realestate','Inmobiliaria'],['casino','Juegos / casino'],['consulting','Asesoría sin activos fijos'],['extractive','Actividad extractiva listada en el material'],['other','Otra actividad']], 'Algunas actividades aparecen como excluidas en la política ilustrada de la PPT. No implica una prohibición universal.')}${selectField('Destino del crédito','destination',[['working','Capital de trabajo',true],['machine','Maquinaria / equipo'],['local','Local / infraestructura'],['receivables','Financiamiento de ventas'],['guarantee','Garantía ante terceros'],['other','Otro']], 'El destino orienta la familia de producto y el plazo.')}${selectField('Garantía disponible','guarantee',[['none','Sin garantía específica',true],['asset','Activo financiado'],['mortgage','Hipoteca'],['liquid','Garantía líquida']], 'La garantía mitiga pérdida, pero no sustituye capacidad.')}</div><div class="evidence-box"><h4>¿De dónde sale cada dato?</h4><div class="check-grid">${checkField('Ventas sustentadas','evSales',true,'Comprobantes/registros consistentes.')}${checkField('Antigüedad sustentada','evTenure',true,'Evidencia de continuidad del negocio.')}${checkField('Patrimonio sustentado','evPatrimony',true,'Relación verificable de activos y pasivos.')}${checkField('Historial revisado','evHistory',true,'Información crediticia disponible.')}${checkField('Destino documentado','evPurpose',true,'Cotización, proforma, contrato u otro sustento.')}</div><div class="evidence-note" data-evidence-note></div></div><div class="qual-box"><h4>Carácter y consistencia del titular</h4><div class="lab-grid">${selectField('Referencias','references',[['good','Favorables',true],['mixed','Mixtas'],['negative','Negativas relevantes']], 'Aporta información cualitativa sobre comportamiento.')}${selectField('Coherencia de la información','consistency',[['good','Consistente',true],['minor','Diferencias por aclarar'],['bad','Contradicciones relevantes']], 'Se contrasta lo declarado con evidencias y fuentes disponibles.')}</div></div><div class="actions"><button class="btn primary" type="submit">Evaluar y comparar escenarios</button></div></form><div id="pymeResult"></div>`;bindLabCommon(host);bindEvidenceWatcher('#pymeForm','pyme');$('#pymeForm').onsubmit=e=>{e.preventDefault();state.stress={drop:false,late:false};evaluatePyme();};}
const EXCLUDED=new Set(['transport','lawyer','accountant','realestate','casino','consulting','extractive']);
function pymeData(){const f=new FormData($('#pymeForm'));let sales=n(f.get('sales')),surplus=n(f.get('surplus'));if(state.stress.drop){sales*=.8;surplus*=.65;}let history=String(f.get('history'));if(state.stress.late&&history==='good')history='minor';return{sales,tenure:n(f.get('tenure')),age:n(f.get('age')),surplus,patrimony:n(f.get('patrimony')),entities:n(f.get('entities')),history,activity:f.get('activity'),destination:f.get('destination'),guarantee:f.get('guarantee'),ev:[f.has('evSales'),f.has('evTenure'),f.has('evPatrimony'),f.has('evHistory'),f.has('evPurpose')],references:f.get('references'),consistency:f.get('consistency')};}
function productFor(dest){return dest==='working'?'Capital de trabajo / línea o pagaré':dest==='machine'?'Financiamiento de inversión o leasing':dest==='local'?'Financiamiento de infraestructura / hipotecario':dest==='receivables'?'Financiamiento de ventas / facturas':dest==='guarantee'?'Carta fianza / garantía':'Evaluación de producto según destino';}
function pymeScenario(d,key){const p=POLICIES[key],params=key==='expansive'?{sales:18000,tenure:9,entities:4,threshold:60}:key==='balanced'?{sales:20000,tenure:12,entities:3,threshold:70}:{sales:25000,tenure:18,entities:2,threshold:80};const salesRaw=Math.min(100,d.sales/params.sales*85),tenureRaw=Math.min(100,d.tenure/params.tenure*80),margin=d.sales?d.surplus/d.sales:0,flowRaw=Math.max(0,Math.min(100,margin/0.20*100)),patRaw=d.patrimony>0?Math.min(100,65+Math.log10(Math.max(1,d.patrimony))*7):15,hist=histRaw(d.history),entityRaw=d.entities<=params.entities?90:Math.max(20,90-(d.entities-params.entities)*22),verify=d.ev.filter(Boolean).length/5*100;const raw={sales:salesRaw,tenure:tenureRaw,flow:flowRaw,patrimony:patRaw,history:hist,entities:entityRaw,verify};const weights=key==='expansive'?{sales:15,tenure:10,flow:25,patrimony:10,history:15,entities:10,verify:15}:key==='balanced'?{sales:15,tenure:10,flow:30,patrimony:10,history:20,entities:5,verify:10}:{sales:10,tenure:10,flow:35,patrimony:15,history:20,entities:5,verify:5};let score=0;Object.entries(weights).forEach(([k,w])=>score+=raw[k]*w/100);score=Math.round(score);const hardExcluded=EXCLUDED.has(d.activity);const ageOk=d.age>=21&&d.age<=69;const qual=qualitativeDecision(d.references,d.consistency,'clear');let final=hardExcluded?'No continúa bajo esta política de ejemplo':!ageOk?'Requiere revisión de política por edad':score>=params.threshold?'Preevaluación favorable':'Requiere profundizar evaluación';if(d.patrimony<0)final='Alerta patrimonial · requiere revisión';const evidenceComplete=d.ev.every(Boolean);if(qual.level==='red'&&final.includes('favorable'))final='Observado · no avanzar sin aclarar carácter/consistencia';else if(!evidenceComplete&&final.includes('favorable'))final='Preevaluación preliminar · evidencia pendiente';else if(qual.level==='amber'&&final.includes('favorable'))final='Preevaluación condicionada a validación';return{key,p,params,raw,weights,score,final,qual,product:productFor(d.destination),excluded:hardExcluded,evidenceComplete};}
function pymeBreakdown(r){const labels={sales:'Ventas',tenure:'Antigüedad',flow:'Excedente/capacidad',patrimony:'Patrimonio',history:'Historial',entities:'Concurrencia',verify:'Evidencia'};return `<div class="calc-list">${Object.keys(r.weights).map(k=>`<div><span>${labels[k]}</span><b>${Math.round(r.raw[k])}/100 × ${r.weights[k]}%</b></div>`).join('')}<div><span>Umbral académico</span><b>${r.params.threshold}/100</b></div><div><span>Producto orientativo</span><b>${esc(r.product)}</b></div></div>`;}
function evaluatePyme(){const d=pymeData(),results=['expansive','balanced','conservative'].map(k=>pymeScenario(d,k)),evg=evidenceGate('pyme',d.ev);const host=$('#pymeResult'),excluded=EXCLUDED.has(d.activity);host.innerHTML=`${evidenceWarning(evg)}${excluded?`<div class="policy-alert"><strong>Alerta de política del ejercicio</strong><p>La actividad seleccionada aparece entre las exclusiones de la política ilustrada en la PPT. Esto no significa que la actividad esté prohibida universalmente; en un caso real se debe verificar la política vigente de la entidad.</p></div>`:''}<div class="lab-summary"><div><strong>Ventas consideradas</strong><span>${money(d.sales)}</span></div><div><strong>Excedente</strong><span>${money(d.surplus)}</span></div><div><strong>Evidencias</strong><span>${d.ev.filter(Boolean).length}/5</span></div><div><strong>Producto orientativo</strong><span>${esc(productFor(d.destination))}</span></div></div>${resultCards(results,'pyme')}${stressControls()}<div class="executive-report"><span class="eyebrow dark">LECTURA EJECUTIVA</span><p><strong>Qué se valoró:</strong> escala de ventas, antigüedad, excedente, patrimonio, historial, concurrencia y evidencia. La actividad puede actuar como filtro de política dentro del ejercicio.</p><p><strong>Política equilibrada:</strong> ${esc(results[1].final)}. Solución orientativa: ${esc(results[1].product)}. ${esc(results[1].qual.effect)}</p>${!evg.complete?`<p><strong>Estado documental:</strong> incompleto. Pendiente: ${esc(evg.missing.join(', '))}. La preevaluación puede continuar, pero no corresponde cerrar aprobación ni desembolso.</p>`:''}<div class="actions"><button class="btn secondary" id="readPymeReport">▶ Leer</button><button class="btn secondary" id="explainPymeReport">💡 Explicar</button></div></div>`;$('#stressApply').onclick=()=>{state.stress.drop=$('#stressDrop').checked;state.stress.late=$('#stressLate').checked;evaluatePyme();};$('#readPymeReport').onclick=()=>speak(`Resultado del preevaluador PyME. Expansivo: ${results[0].final}. Equilibrado: ${results[1].final}. Conservador: ${results[2].final}. Producto orientativo: ${results[1].product}.`);$('#explainPymeReport').onclick=()=>speak('El evaluador PyME no se limita a una nota. Usa datos del negocio, evidencia, conducta y reglas de política. Un cambio de apetito modifica umbrales y pesos, mientras que ciertas restricciones de política pueden impedir continuar incluso con un buen resultado numérico.');host.scrollIntoView({behavior:'smooth',block:'start'});}

function renderEmpresa(){const host=$('#labHost');host.innerHTML=`${commonLabHeader('Evaluador de estructuración empresarial','Herramienta breve: no pretende aprobar una empresa con pocos datos. Identifica nivel de análisis y posibles familias de solución.',17,'assets/pista_productos.m4a')}<form id="empresaForm" class="lab-form"><div class="lab-grid">${field('Ventas mensuales estimadas (S/)','sales',450000,'Evidencia: estados financieros, declaraciones y trazabilidad comercial.')}${field('Antigüedad de la empresa (años)','years',6,'Evidencia societaria, tributaria y operativa.')}${field('Monto solicitado (S/)','requested',250000,'Se analiza junto con destino, flujo y estructura de deuda.')}${selectField('Destino','destination',[['working','Capital de trabajo',false],['machine','Maquinaria / equipo',true],['local','Local / infraestructura'],['guarantee','Garantía ante terceros']], 'El destino orienta la estructura: inversión, leasing, capital de trabajo o carta fianza.')}${selectField('Nivel de endeudamiento','debt',[['low','Bajo'],['medium','Medio',true],['high','Alto']], 'No reemplaza ratios financieros; es una aproximación didáctica para esta sesión.')}${selectField('Estabilidad del flujo operativo','flow',[['stable','Estable',true],['variable','Variable'],['weak','Deteriorado']], 'En la sesión 4 se podrá profundizar con estados financieros y ratios.')}${selectField('Garantía / respaldo','guarantee',[['none','Sin garantía específica'],['asset','Activo financiado',true],['mortgage','Hipoteca'],['liquid','Garantía líquida']], 'Ayuda a mitigar riesgo, pero no sustituye flujo.')}${selectField('Complejidad de la operación','complexity',[['standard','Estándar'],['structured','Estructurada',true]], 'Operaciones complejas requieren análisis y documentación más profundos.')}</div><div class="evidence-box"><h4>Evidencia mínima para validar la decisión</h4><div class="check-grid">${checkField('Estados financieros disponibles','evFs',true,'Base para profundizar capacidad y endeudamiento.')}${checkField('Información tributaria disponible','evTax',true,'Apoya consistencia de ventas y actividad.')}${checkField('Reporte de obligaciones','evDebt',true,'Permite observar exposición y concurrencia.')}${checkField('Destino documentado','evPurpose',true,'Cotizaciones, contratos o proyecto de inversión.')}</div><div class="evidence-note" data-evidence-note></div></div><div class="qual-box"><h4>Consistencia cualitativa</h4><div class="lab-grid">${selectField('Referencias comerciales','references',[['good','Favorables',true],['mixed','Mixtas'],['negative','Negativas relevantes']], 'Aporta contexto sobre cumplimiento y relación con terceros.')}${selectField('Coherencia de la información','consistency',[['good','Consistente',true],['minor','Diferencias por aclarar'],['bad','Contradicciones relevantes']], 'Una operación estructurada exige trazabilidad documental.')}</div></div><div class="actions"><button class="btn primary" type="submit">Evaluar y comparar escenarios</button></div></form><div id="empresaResult"></div>`;bindLabCommon(host);bindEvidenceWatcher('#empresaForm','empresa');$('#empresaForm').onsubmit=e=>{e.preventDefault();state.stress={drop:false,late:false};evaluateEmpresa();};}
function empresaData(){const f=new FormData($('#empresaForm'));let sales=n(f.get('sales'));if(state.stress.drop)sales*=.8;let flow=String(f.get('flow'));if(state.stress.late&&flow==='stable')flow='variable';return{sales,years:n(f.get('years')),requested:n(f.get('requested')),destination:f.get('destination'),debt:f.get('debt'),flow,guarantee:f.get('guarantee'),complexity:f.get('complexity'),ev:[f.has('evFs'),f.has('evTax'),f.has('evDebt'),f.has('evPurpose')],references:f.get('references'),consistency:f.get('consistency')};}
function empresaScenario(d,key){const p=POLICIES[key],flowRaw=d.flow==='stable'?95:d.flow==='variable'?65:30,debtRaw=d.debt==='low'?95:d.debt==='medium'?70:35,yearsRaw=d.years>=5?95:d.years>=3?80:d.years>=1?60:35,verify=d.ev.filter(Boolean).length/4*100,structure=d.complexity==='standard'?85:(key==='expansive'?80:key==='balanced'?70:60),guar=d.guarantee==='liquid'?100:d.guarantee==='mortgage'?95:d.guarantee==='asset'?80:45;const raw={flow:flowRaw,debt:debtRaw,years:yearsRaw,verify,structure,guarantee:guar};const weights=key==='expansive'?{flow:25,debt:15,years:10,verify:15,structure:20,guarantee:15}:key==='balanced'?{flow:30,debt:20,years:10,verify:20,structure:10,guarantee:10}:{flow:35,debt:25,years:10,verify:20,structure:5,guarantee:5};let score=0;Object.entries(weights).forEach(([k,w])=>score+=raw[k]*w/100);score=Math.round(score);const threshold=key==='expansive'?62:key==='balanced'?72:82,qual=qualitativeDecision(d.references,d.consistency,'clear');let final=score>=threshold?'Viable para análisis estructurado':'Requiere profundizar antes de continuar';const evidenceComplete=d.ev.every(Boolean);if(qual.level==='red')final='Observado · requiere aclaración cualitativa';else if(!evidenceComplete&&score>=threshold)final='Análisis preliminar · evidencia pendiente';else if(qual.level==='amber'&&score>=threshold)final='Viable con validaciones adicionales';return{key,p,raw,weights,score,threshold,final,qual,product:productFor(d.destination),note:'No es aprobación final',evidenceComplete};}
function empresaBreakdown(r){const labels={flow:'Flujo operativo',debt:'Endeudamiento',years:'Antigüedad',verify:'Evidencia',structure:'Complejidad',guarantee:'Respaldo'};return `<div class="calc-list">${Object.keys(r.weights).map(k=>`<div><span>${labels[k]}</span><b>${Math.round(r.raw[k])}/100 × ${r.weights[k]}%</b></div>`).join('')}<div><span>Umbral académico</span><b>${r.threshold}/100</b></div><div><span>Familia de solución</span><b>${esc(r.product)}</b></div></div>`;}
function evaluateEmpresa(){const d=empresaData(),results=['expansive','balanced','conservative'].map(k=>empresaScenario(d,k)),evg=evidenceGate('empresa',d.ev);const host=$('#empresaResult');host.innerHTML=`${evidenceWarning(evg)}<div class="lab-summary"><div><strong>Ventas consideradas</strong><span>${money(d.sales)}</span></div><div><strong>Evidencias</strong><span>${d.ev.filter(Boolean).length}/4</span></div><div><strong>Solución orientativa</strong><span>${esc(productFor(d.destination))}</span></div><div><strong>Alcance</strong><span>No es aprobación final</span></div></div>${resultCards(results,'empresa')}${stressControls()}<div class="executive-report"><span class="eyebrow dark">LECTURA EJECUTIVA</span><p><strong>Qué se valoró:</strong> estabilidad de flujo, endeudamiento, antigüedad, evidencia, complejidad y respaldo. El resultado indica si conviene profundizar una estructuración, no si la empresa está aprobada.</p><p><strong>Política equilibrada:</strong> ${esc(results[1].final)}. Familia de solución: ${esc(results[1].product)}. La Sesión 4 será el espacio natural para profundizar estados financieros y riesgos.</p>${!evg.complete?`<p><strong>Estado documental:</strong> incompleto. Pendiente: ${esc(evg.missing.join(', '))}. Se puede continuar con el análisis preliminar, pero no cerrar aprobación ni desembolso.</p>`:''}<div class="actions"><button class="btn secondary" id="readEmpresaReport">▶ Leer</button><button class="btn secondary" id="explainEmpresaReport">💡 Explicar</button></div></div>`;$('#stressApply').onclick=()=>{state.stress.drop=$('#stressDrop').checked;state.stress.late=$('#stressLate').checked;evaluateEmpresa();};$('#readEmpresaReport').onclick=()=>speak(`Evaluación empresarial orientativa. Expansiva: ${results[0].final}. Equilibrada: ${results[1].final}. Conservadora: ${results[2].final}.`);$('#explainEmpresaReport').onclick=()=>speak('En Banca Empresa evitamos fingir un scoring definitivo con pocos datos. La herramienta solo muestra cómo la tolerancia al riesgo puede cambiar la disposición a continuar y qué evidencia sería necesaria para una estructuración más profunda.');host.scrollIntoView({behavior:'smooth',block:'start'});}

/* quiz */
function resetQuiz(){state.quizOrder=shuffleIndices(DATA.quiz.length);state.quizIndex=0;state.quizStates={};state.quizScore=0;$('#scoreCard').classList.add('hidden');ensureQuiz();}
function ensureQuiz(){if(!state.quizOrder.length)state.quizOrder=shuffleIndices(DATA.quiz.length);renderQuizItem();}
function quizState(idx,q){return state.quizStates[idx]||(state.quizStates[idx]=createQState(q));}
function renderQuizItem(){if(state.quizIndex>=DATA.quiz.length){finishQuiz();return;}const qi=state.quizOrder[state.quizIndex],q=DATA.quiz[qi],qs=quizState(qi,q);$('#quizBadge').textContent=`Pregunta ${state.quizIndex+1} / ${DATA.quiz.length}`;$('#quizBar').style.width=`${state.quizIndex/DATA.quiz.length*100}%`;$('#quizHost').innerHTML='<div id="quizQuestion"></div><div id="quizNext"></div>';renderQuestion($('#quizQuestion'),q,qs,{onFinish:r=>{if(r.correct&&!qs._counted){state.quizScore++;qs._counted=true;}renderQuizItem();}});if(questionDone(qs)){$('#quizNext').innerHTML=`<button class="btn teal" style="margin-top:.7rem">${state.quizIndex===DATA.quiz.length-1?'Ver resultado':'Siguiente pregunta →'}</button>`;$('#quizNext button').onclick=()=>{state.quizIndex++;renderQuizItem();window.scrollTo({top:0,behavior:'smooth'});};}}
function finishQuiz(){$('#quizBar').style.width='100%';$('#quizHost').innerHTML='';$('#scoreCard').classList.remove('hidden');$('#scoreTitle').textContent=`${state.quizScore} de ${DATA.quiz.length} respuestas correctas sin Ruta correcta`;$('#scoreText').textContent=state.quizScore>=5?'Tu criterio distingue segmentación, evidencia, scoring, carácter y apetito de riesgo con bastante solidez.':state.quizScore>=3?'Tienes una base funcional. Revisa especialmente cómo se conectan evidencia, carácter y políticas de riesgo.':'Conviene regresar a las tarjetas y al laboratorio antes de repetir la comprobación.';}

/* resources */
function renderResources(){const host=$('#resourceGrid');host.innerHTML=DATA.resources.map(r=>`<article class="resource-card"><div class="resource-thumb"><img src="${r.thumb}" alt="Miniatura de ${esc(r.title)}"></div><div class="resource-copy"><h3>${esc(r.title)}</h3><p>${esc(r.desc)}</p><button class="btn secondary" data-open-resource="${r.id}">Abrir dentro del programa</button></div></article>`).join('');$$('[data-open-resource]',host).forEach(b=>b.onclick=()=>openResource(b.dataset.openResource,0));}
const VIDEO_MAP={'video-main':'assets/video_apertura.mp4','video-short':'assets/microvideo_segmentacion.mp4','video-clip':'assets/microvideo_evaluacion_dual_17s.mp4'};
function openResource(id,index=0){if(VIDEO_MAP[id])return openFloatingVideo(id);resourceContext={id,index};renderResource();openDialog('resourceModal');}
function openFloatingVideo(id){const r=DATA.resources.find(x=>x.id===id),v=$('#floatingVideo');v.src=VIDEO_MAP[id];v.setAttribute('aria-label',r?.title||'Video');openDialog('videoModal');setTimeout(()=>v.play().catch(()=>{}),80);}
function resourceMeta(){return DATA.resources.find(x=>x.id===resourceContext?.id);}
function resourceSpeech(type){const id=resourceContext.id,idx=resourceContext.index||0;if(id==='ppt')return RT.ppt?.[idx]?.[type]||'';if(id==='pdf')return RT.pdf?.[idx]?.[type]||'';return RT[id]?.[type]||'';}
function renderResource(){const r=resourceMeta();if(!r)return;$('#resourceType').textContent=r.type.toUpperCase();$('#resourceTitle').textContent=r.title;const body=$('#resourceBody'),foot=$('#resourceFooter');body.className='resource-body';if(r.id==='ppt'){const i=Math.max(0,Math.min(17,resourceContext.index||0));resourceContext.index=i;body.innerHTML=`<div class="fit-stage"><img src="assets/ppt/slide-${String(i+1).padStart(2,'0')}.png" alt="Diapositiva ${i+1} de 18" data-image="assets/ppt/slide-${String(i+1).padStart(2,'0')}.png"></div>`;foot.innerHTML=`<div class="resource-nav"><button data-rnav="-1" ${i===0?'disabled':''}>← Anterior</button><strong>Diapositiva ${i+1} / 18</strong><button data-rnav="1" ${i===17?'disabled':''}>Siguiente →</button></div>${speechControlsHTML()}`;bindResourceNav(18);}else if(r.id==='pdf'){const i=Math.max(0,Math.min(13,resourceContext.index||0));resourceContext.index=i;body.innerHTML=`<div class="fit-stage"><img src="assets/pdf/page-${String(i+1).padStart(2,'0')}.png" alt="Página ${i+1} de 14" data-image="assets/pdf/page-${String(i+1).padStart(2,'0')}.png"></div>`;foot.innerHTML=`<div class="resource-nav"><button data-rnav="-1" ${i===0?'disabled':''}>← Anterior</button><strong>Página ${i+1} / 14</strong><button data-rnav="1" ${i===13?'disabled':''}>Siguiente →</button></div>${speechControlsHTML()}`;bindResourceNav(14);}else if(r.id==='infographic'){body.innerHTML=`<div class="fit-stage"><img src="assets/infografia_banca_pyme.png" alt="Infografía de evaluación y soluciones Banca PyME" data-image="assets/infografia_banca_pyme.png"></div>`;foot.innerHTML=`<div class="resource-nav"><strong>Infografía de la sesión</strong></div>${speechControlsHTML()}`;}else if(r.id==='audio'){body.innerHTML=`<div class="audio-stage"><div class="audio-card"><img src="assets/thumbs/audio.png" alt="Resumen de audio"><h3>Cómo deciden los bancos financiar tu PyME</h3><audio controls preload="metadata"><source src="assets/podcast_completo.m4a" type="audio/mp4"></audio></div></div>`;foot.innerHTML=`<div class="resource-nav"><strong>Audio completo</strong></div>${speechControlsHTML()}`;}bindSpeechControls(foot,type=>resourceSpeech(type));$('[data-image]',body)?.addEventListener('click',e=>openImage(e.currentTarget.dataset.image,e.currentTarget.alt));}
function bindResourceNav(total){$$('[data-rnav]',$('#resourceFooter')).forEach(b=>b.onclick=()=>{resourceContext.index=Math.max(0,Math.min(total-1,(resourceContext.index||0)+Number(b.dataset.rnav)));stopSpeech();renderResource();});}
function openImage(src,alt='Vista ampliada'){$('#imageModalImg').src=src;$('#imageModalImg').alt=alt;openDialog('imageModal');}

/* aula virtual */
async function returnToAulaVirtual(){
  if(typeof stopSpeech==='function')stopSpeech();
  try{if(document.fullscreenElement)await document.exitFullscreen();}catch(_e){}
  window.location.href=new URL('../',window.location.href).href;
}

/* bindings */
$('#aulaHomeBtn')?.addEventListener('click',returnToAulaVirtual);
$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('.modal-close').forEach(b=>b.onclick=()=>closeDialog(b.dataset.close));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)closeDialog(d.id);}));$('#prevConcept').onclick=()=>{conceptIndex=Math.max(0,conceptIndex-1);renderConceptModal();setTimeout(()=>$('#conceptBody').scrollTo({top:0}),20);};$('#nextConcept').onclick=()=>{conceptIndex=Math.min(DATA.concepts.length-1,conceptIndex+1);renderConceptModal();setTimeout(()=>$('#conceptBody').scrollTo({top:0}),20);};$('#resourceFull').onclick=()=>toggleFullscreen($('#resourceShell'));$('#fullBtn').onclick=()=>toggleFullscreen($('.app-shell'));$('#fontMinus').onclick=()=>{state.font=Math.max(.88,state.font-.08);updateFont();};$('#fontPlus').onclick=()=>{state.font=Math.min(1.24,state.font+.08);updateFont();};$('#soundBtn').onclick=()=>{state.sound=!state.sound;$('#soundBtn').textContent=state.sound?'🔊':'🔇';};$('#themeBtn').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';applyTheme();};$('#layoutSelect').onchange=e=>{state.layout=e.target.value;applyLayout();};$('#restartQuiz').onclick=resetQuiz;$$('[data-open-resource]').forEach(b=>b.onclick=()=>openResource(b.dataset.openResource,Number(b.dataset.resourceIndex||0)));$$('.lab-tab').forEach(b=>b.onclick=()=>{state.lab=b.dataset.lab;state.stress={drop:false,late:false};renderLab();});window.addEventListener('resize',()=>{if(state.layout==='auto')applyLayout();});if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=()=>{};
applyLayout();applyTheme();updateFont();renderConceptCards();renderLab();renderResources();resetQuiz();
